/* ta_BBANDS.c */
static inline TA_RetCode TA_BBANDS( int    startIdx,
                                 int    endIdx,
                                 const double inReal[],
                                 int optInTimePeriod,
                                 double optInNbDevUp,
                                 double optInNbDevDn,
                                 TA_MAType optInMAType,
                                 int          *outBegIdx,
                                 int          *outNBElement,
                                 double        outRealUpperBand[],
                                 double        outRealMiddleBand[],
                                 double        outRealLowerBand[] )
{
   TA_RetCode retCode;
   int i;
   int maBegIdx;
   int shiftIdx;
   double tempReal;
   double tempReal2;
   double *tempBuffer1;
   double *tempBuffer2;
   if( (startIdx < 0) || (startIdx > TA_MAX_INDEX) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > TA_MAX_INDEX) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInTimePeriod == TA_INTEGER_DEFAULT )
      optInTimePeriod = 20;
   else if( (int)optInTimePeriod < 2 || (int)optInTimePeriod > 100000 )
      return TA_BAD_PARAM;
   if( optInNbDevUp == TA_REAL_DEFAULT )
      optInNbDevUp = 2;
   else if( !(optInNbDevUp >= TA_REAL_MIN && optInNbDevUp <= TA_REAL_MAX) )
      return TA_BAD_PARAM;
   if( optInNbDevDn == TA_REAL_DEFAULT )
      optInNbDevDn = 2;
   else if( !(optInNbDevDn >= TA_REAL_MIN && optInNbDevDn <= TA_REAL_MAX) )
      return TA_BAD_PARAM;
   if( (int)optInMAType == TA_INTEGER_DEFAULT || optInMAType == TA_MAType_DEFAULT )
      optInMAType = 0;
   else if( (int)optInMAType < TA_MATYPE_MIN || (int)optInMAType > TA_MATYPE_MAX )
      return TA_BAD_PARAM;
   if( !inReal )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outRealUpperBand )
      return TA_BAD_PARAM;
   if( !outRealMiddleBand )
      return TA_BAD_PARAM;
   if( !outRealLowerBand )
      return TA_BAD_PARAM;
   if( outRealUpperBand == outRealMiddleBand || outRealUpperBand == outRealLowerBand || outRealMiddleBand == outRealLowerBand )
      return TA_BAD_PARAM;
   if( optInMAType == TA_MAType_SMA )
   {
      if( inReal == outRealUpperBand )
      {
         tempBuffer1 = outRealMiddleBand;
         tempBuffer2 = outRealLowerBand;
      } else if( inReal == outRealLowerBand )
      {
         tempBuffer1 = outRealMiddleBand;
         tempBuffer2 = outRealUpperBand;
      } else if( inReal == outRealMiddleBand )
      {
         tempBuffer1 = outRealLowerBand;
         tempBuffer2 = outRealUpperBand;
      } else
      {
         tempBuffer1 = outRealMiddleBand;
         tempBuffer2 = outRealUpperBand;
      }
      if( tempBuffer1 == inReal || tempBuffer2 == inReal )
      {
         return TA_BAD_PARAM;
      }
      double maTotal;
      double shift;
      double varTotal1;
      double varTotal2;
      double meanValue1;
      double variance;
      double _invPeriod;
      double _tempReal;
      int _i;
      int _j;
      int _outIdx;
      int _trailingIdx;
      int _windowStart;
      int _lookbackTotal;
      int _barsSinceReseed;
      _lookbackTotal = optInTimePeriod - 1;
      if( startIdx < _lookbackTotal )
      {
         startIdx = _lookbackTotal;
      }
      if( startIdx > endIdx )
      {
         *outBegIdx= 0;
         *outNBElement= 0;
         return TA_SUCCESS;
      }
      _invPeriod = 1.0 / (double)optInTimePeriod;
      _trailingIdx = startIdx - _lookbackTotal;
      shift = inReal[_trailingIdx];
      maTotal = 0.0;
      varTotal1 = 0.0;
      varTotal2 = 0.0;
      for( _j = _trailingIdx; _j < startIdx; _j += 1 )
      {
         maTotal += inReal[_j];
         _tempReal = inReal[_j] - shift;
         varTotal1 += _tempReal;
         _tempReal *= _tempReal;
         varTotal2 += _tempReal;
      }
      _i = startIdx;
      _outIdx = 0;
      _barsSinceReseed = 32 * optInTimePeriod;
      do
      {
         maTotal += inReal[_i];
         _tempReal = inReal[_i] - shift;
         varTotal1 += _tempReal;
         _tempReal *= _tempReal;
         varTotal2 += _tempReal;
         meanValue1 = varTotal1 * _invPeriod;
         variance = varTotal2 * _invPeriod - meanValue1 * meanValue1;
         tempBuffer1[_outIdx] = maTotal / optInTimePeriod;
         maTotal -= inReal[_trailingIdx];
         _tempReal = inReal[_trailingIdx] - shift;
         varTotal1 -= _tempReal;
         _tempReal *= _tempReal;
         varTotal2 -= _tempReal;
         _trailingIdx += 1;
         _barsSinceReseed -= 1;
         if( variance < 0.000001 * (varTotal2 * _invPeriod) || _tempReal > 1000000.0 * varTotal2 || _barsSinceReseed <= 0 )
         {
            _barsSinceReseed = 32 * optInTimePeriod;
            _windowStart = _i - _lookbackTotal;
            _tempReal = 0.0;
            for( _j = _windowStart; _j <= _i; _j += 1 )
            {
               _tempReal += inReal[_j];
            }
            shift = _tempReal * _invPeriod;
            varTotal1 = 0.0;
            varTotal2 = 0.0;
            for( _j = _windowStart; _j <= _i; _j += 1 )
            {
               _tempReal = inReal[_j] - shift;
               varTotal1 += _tempReal;
               _tempReal *= _tempReal;
               varTotal2 += _tempReal;
            }
            meanValue1 = varTotal1 * _invPeriod;
            variance = varTotal2 * _invPeriod - meanValue1 * meanValue1;
            if( variance < 0.000000000001 * (varTotal2 * _invPeriod) )
            {
               variance = 0.0;
            }
            _tempReal = inReal[_windowStart] - shift;
            varTotal1 -= _tempReal;
            _tempReal *= _tempReal;
            varTotal2 -= _tempReal;
         }
         tempBuffer2[_outIdx] = (variance != 0.0) ? sqrt(variance) : 0.0;
         _outIdx += 1;
         _i += 1;
      } while( _i <= endIdx );
      *outNBElement= _outIdx;
      *outBegIdx= startIdx;
      if( tempBuffer1 != outRealMiddleBand )
      {
         memcpy(outRealMiddleBand,tempBuffer1,*outNBElement * sizeof(double));
      }
      if( optInNbDevUp == optInNbDevDn )
      {
         for( i = 0; i < (int)*outNBElement; i += 1 )
         {
            tempReal = tempBuffer2[i] * optInNbDevUp;
            tempReal2 = outRealMiddleBand[i];
            outRealUpperBand[i] = tempReal2 + tempReal;
            outRealLowerBand[i] = tempReal2 - tempReal;
         }
      } else
      {
         for( i = 0; i < (int)*outNBElement; i += 1 )
         {
            tempReal = tempBuffer2[i];
            tempReal2 = outRealMiddleBand[i];
            outRealUpperBand[i] = fma(tempReal, optInNbDevUp, tempReal2);
            outRealLowerBand[i] = tempReal2 - tempReal * optInNbDevDn;
         }
      }
      return TA_SUCCESS;
   }
   if( TA_BBANDS_Lookback(optInTimePeriod,optInNbDevUp,optInNbDevDn,optInMAType) > endIdx )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_SUCCESS;
   }
   tempBuffer1 = TA_Malloc((endIdx - startIdx + 1) * sizeof(double));
   if( !tempBuffer1 )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_ALLOC_ERR;
   }
   tempBuffer2 = TA_Malloc((endIdx - startIdx + 1) * sizeof(double));
   if( !tempBuffer2 )
   {
      free(tempBuffer1);
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_ALLOC_ERR;
   }
   retCode = TA_MA(startIdx,endIdx,inReal,optInTimePeriod,optInMAType,outBegIdx,outNBElement,tempBuffer1);
   if( retCode != TA_SUCCESS || (int)*outNBElement == 0 )
   {
      *outNBElement= 0;
      free(tempBuffer1);
      free(tempBuffer2);
      return retCode;
   }
   maBegIdx = (int)*outBegIdx;
   retCode = TA_STDDEV((int)*outBegIdx,endIdx,inReal,optInTimePeriod,1.0,outBegIdx,outNBElement,tempBuffer2);
   if( retCode != TA_SUCCESS )
   {
      *outNBElement= 0;
      free(tempBuffer1);
      free(tempBuffer2);
      return retCode;
   }
   if( (int)*outBegIdx > maBegIdx )
   {
      shiftIdx = (int)*outBegIdx - maBegIdx;
   } else
   {
      shiftIdx = 0;
   }
   memmove(outRealMiddleBand,&tempBuffer1[shiftIdx],*outNBElement * sizeof(double));
   if( optInNbDevUp == optInNbDevDn )
   {
      for( i = 0; i < (int)*outNBElement; i += 1 )
      {
         tempReal = tempBuffer2[i] * optInNbDevUp;
         tempReal2 = outRealMiddleBand[i];
         outRealUpperBand[i] = tempReal2 + tempReal;
         outRealLowerBand[i] = tempReal2 - tempReal;
      }
   } else
   {
      for( i = 0; i < (int)*outNBElement; i += 1 )
      {
         tempReal2 = outRealMiddleBand[i];
         outRealUpperBand[i] = fma(tempBuffer2[i], optInNbDevUp, tempReal2);
         outRealLowerBand[i] = tempReal2 - tempBuffer2[i] * optInNbDevDn;
      }
   }
   free(tempBuffer1);
   free(tempBuffer2);
   return TA_SUCCESS;
}

/* ta_BBANDS.c */
static inline int TA_BBANDS_Lookback( int optInTimePeriod, double optInNbDevUp, double optInNbDevDn, TA_MAType optInMAType )
{
   int maLookback;
   int stddevLookback;
   if( (int)optInTimePeriod == TA_INTEGER_DEFAULT )
      optInTimePeriod = 20;
   else if( (int)optInTimePeriod < 2 || (int)optInTimePeriod > 100000 )
      return -1;
   if( optInNbDevUp == TA_REAL_DEFAULT )
      optInNbDevUp = 2;
   else if( !(optInNbDevUp >= TA_REAL_MIN && optInNbDevUp <= TA_REAL_MAX) )
      return -1;
   if( optInNbDevDn == TA_REAL_DEFAULT )
      optInNbDevDn = 2;
   else if( !(optInNbDevDn >= TA_REAL_MIN && optInNbDevDn <= TA_REAL_MAX) )
      return -1;
   if( (int)optInMAType == TA_INTEGER_DEFAULT || optInMAType == TA_MAType_DEFAULT )
      optInMAType = 0;
   else if( (int)optInMAType < TA_MATYPE_MIN || (int)optInMAType > TA_MATYPE_MAX )
      return -1;
   maLookback = TA_MA_Lookback(optInTimePeriod,optInMAType);
   stddevLookback = TA_STDDEV_Lookback(optInTimePeriod,1.0);
   return (maLookback > stddevLookback) ? maLookback : stddevLookback;
}

/* ta_BOP.c */
static inline TA_RetCode TA_BOP( int    startIdx,
                              int    endIdx,
                              const double inOpen[],
                              const double inHigh[],
                              const double inLow[],
                              const double inClose[],
                              int          *outBegIdx,
                              int          *outNBElement,
                              double        outReal[] )
{
   int outIdx;
   int i;
   double tempReal;
   if( (startIdx < 0) || (startIdx > TA_MAX_INDEX) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > TA_MAX_INDEX) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( !inOpen )
      return TA_BAD_PARAM;
   if( !inHigh )
      return TA_BAD_PARAM;
   if( !inLow )
      return TA_BAD_PARAM;
   if( !inClose )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   outIdx = 0;
   for( i = startIdx; i <= endIdx; i += 1 )
   {
      tempReal = inHigh[i] - inLow[i];
      if( tempReal <= 0.0 )
      {
         outReal[outIdx++] = 0.0;
      } else
      {
         outReal[outIdx++] = (inClose[i] - inOpen[i]) / tempReal;
      }
   }
   *outNBElement= outIdx;
   *outBegIdx= startIdx;
   return TA_SUCCESS;
}

