/* ta_CCI.c */
static inline TA_RetCode TA_CCI( int    startIdx,
                              int    endIdx,
                              const double inHigh[],
                              const double inLow[],
                              const double inClose[],
                              int optInTimePeriod,
                              int          *outBegIdx,
                              int          *outNBElement,
                              double        outReal[] )
{
   double tempReal;
   double tempReal2;
   double tempReal3;
   double theAverage;
   double lastValue;
   int i;
   int j;
   int outIdx;
   int lookbackTotal;
   double local_circBuffer[30];
   double *circBuffer = &local_circBuffer[0];
   int circBuffer_Idx;
   int maxIdx_circBuffer;
   if( (startIdx < 0) || (startIdx > TA_MAX_INDEX) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > TA_MAX_INDEX) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInTimePeriod == TA_INTEGER_DEFAULT )
      optInTimePeriod = 14;
   else if( (int)optInTimePeriod < 2 || (int)optInTimePeriod > 100000 )
      return TA_BAD_PARAM;
   if( !inHigh )
      return TA_BAD_PARAM;
   if( !inLow )
      return TA_BAD_PARAM;
   if( !inClose )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   lookbackTotal = optInTimePeriod - 1;
   if( startIdx < lookbackTotal )
   {
      startIdx = lookbackTotal;
   }
   if( startIdx > endIdx )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_SUCCESS;
   }
   if( optInTimePeriod < 1 ) return TA_INTERNAL_ERROR(192);
   if( (int)optInTimePeriod > (int)(sizeof(local_circBuffer)/sizeof(double)) )
   {
      circBuffer = TA_Malloc( sizeof(double)*optInTimePeriod );
      if( !circBuffer )
      {
         return TA_ALLOC_ERR;
      }
   }
   else
   {
      circBuffer = &local_circBuffer[0];
   }
   maxIdx_circBuffer = (optInTimePeriod-1);
   circBuffer_Idx = 0;
   i = startIdx - lookbackTotal;
   if( optInTimePeriod > 1 )
   {
      while( i < startIdx )
      {
         circBuffer[circBuffer_Idx] = (inHigh[i] + inLow[i] + inClose[i]) / 3;
         i += 1;
         circBuffer_Idx++;
         if( circBuffer_Idx > maxIdx_circBuffer ) circBuffer_Idx = 0;
      }
   }
   outIdx = 0;
   do
   {
      lastValue = (inHigh[i] + inLow[i] + inClose[i]) / 3;
      circBuffer[circBuffer_Idx] = lastValue;
      theAverage = 0;
      for( j = 0; j < optInTimePeriod; j += 1 )
      {
         theAverage += circBuffer[j];
      }
      theAverage /= optInTimePeriod;
      tempReal2 = 0;
      for( j = 0; j < optInTimePeriod; j += 1 )
      {
         tempReal2 += fabs(circBuffer[j] - theAverage);
      }
      tempReal2 /= optInTimePeriod;
      tempReal = lastValue - theAverage;
      tempReal3 = fabs(theAverage);
      if( !TA_IS_ZERO_SCALED(tempReal, tempReal3) && !TA_IS_ZERO_SCALED(tempReal2, tempReal3) && 0.015 * tempReal2 != 0.0 )
      {
         outReal[outIdx++] = tempReal / (0.015 * tempReal2);
      } else
      {
         outReal[outIdx++] = 0.0;
      }
      circBuffer_Idx++;
      if( circBuffer_Idx > maxIdx_circBuffer ) circBuffer_Idx = 0;
      i += 1;
   } while( i <= endIdx );
   *outNBElement= outIdx;
   *outBegIdx= startIdx;
   if( circBuffer != &local_circBuffer[0] ) { TA_Free( circBuffer ); circBuffer = &local_circBuffer[0]; }
   return TA_SUCCESS;
}

/* ta_CCI.c */
static inline int TA_CCI_Lookback( int optInTimePeriod )
{
   if( (int)optInTimePeriod == TA_INTEGER_DEFAULT )
      optInTimePeriod = 14;
   else if( (int)optInTimePeriod < 2 || (int)optInTimePeriod > 100000 )
      return -1;
   return optInTimePeriod - 1;
}

/* ta_CDL2CROWS.c */
static inline TA_RetCode TA_CDL2CROWS( int    startIdx,
                                    int    endIdx,
                                    const double inOpen[],
                                    const double inHigh[],
                                    const double inLow[],
                                    const double inClose[],
                                    int          *outBegIdx,
                                    int          *outNBElement,
                                    int        outInteger[] )
{
   double BodyLongPeriodTotal;
   int i;
   int outIdx;
   int BodyLongTrailingIdx;
   int lookbackTotal;
   int BodyLong_avgPeriod = TA_Globals->candleSettings[TA_BodyLong].avgPeriod;
   if( (startIdx < 0) || (startIdx > TA_MAX_INDEX) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > TA_MAX_INDEX) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( !inOpen )
      return TA_BAD_PARAM;
   if( !inHigh )
      return TA_BAD_PARAM;
   if( !inLow )
      return TA_BAD_PARAM;
   if( !inClose )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outInteger )
      return TA_BAD_PARAM;
   lookbackTotal = TA_CDL2CROWS_Lookback();
   if( startIdx < lookbackTotal )
   {
      startIdx = lookbackTotal;
   }
   if( startIdx > endIdx )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_SUCCESS;
   }
   BodyLongPeriodTotal = 0;
   BodyLongTrailingIdx = startIdx - 2 - BodyLong_avgPeriod;
   i = BodyLongTrailingIdx;
   while( i < startIdx - 2 )
   {
      BodyLongPeriodTotal += TA_CANDLERANGE(BodyLong,i);
      i += 1;
   }
   i = startIdx;
   outIdx = 0;
   do
   {
      if( ((inClose[i - 2] >= inOpen[i - 2]) ? 1 : 0 - 1) == 1 &&
          fabs(inClose[i - 2] - inOpen[i - 2]) > TA_CANDLEAVERAGE(BodyLong,BodyLongPeriodTotal,i - 2) &&
          ((inClose[i - 1] >= inOpen[i - 1]) ? 1 : 0 - 1) == 0 - 1 &&
          ((min(inOpen[i - 1],inClose[i - 1]) > max(inOpen[i - 2],inClose[i - 2])) ? 1 : 0) &&
          ((inClose[i] >= inOpen[i]) ? 1 : 0 - 1) == 0 - 1 &&
          inOpen[i] < inOpen[i - 1] &&
          inOpen[i] > inClose[i - 1] &&
          inClose[i] > inOpen[i - 2] &&
          inClose[i] < inClose[i - 2] )
      {
         outInteger[outIdx++] = 0 - 100;
      } else
      {
         outInteger[outIdx++] = 0;
      }
      BodyLongPeriodTotal += TA_CANDLERANGE(BodyLong,i - 2) - TA_CANDLERANGE(BodyLong,BodyLongTrailingIdx);
      i += 1;
      BodyLongTrailingIdx += 1;
   } while( i <= endIdx );
   *outNBElement= outIdx;
   *outBegIdx= startIdx;
   return TA_SUCCESS;
}

/* ta_CDL2CROWS.c */
static inline int TA_CDL2CROWS_Lookback( void )
{
   int BodyLong_avgPeriod = TA_Globals->candleSettings[TA_BodyLong].avgPeriod;
   return BodyLong_avgPeriod + 2;
}

