/* ta_CDLHIKKAKE.c */
static inline TA_RetCode TA_CDLHIKKAKE( int    startIdx,
                                     int    endIdx,
                                     const double inOpen[],
                                     const double inHigh[],
                                     const double inLow[],
                                     const double inClose[],
                                     int          *outBegIdx,
                                     int          *outNBElement,
                                     int        outInteger[] )
{
   int i;
   int outIdx;
   int lookbackTotal;
   int patternResult;
   int cd;
   double savedHigh;
   double savedLow;
   if( (startIdx < 0) || (startIdx > TA_MAX_INDEX) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > TA_MAX_INDEX) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( !inOpen )
      return TA_BAD_PARAM;
   if( !inHigh )
      return TA_BAD_PARAM;
   if( !inLow )
      return TA_BAD_PARAM;
   if( !inClose )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outInteger )
      return TA_BAD_PARAM;
   savedHigh = 0.0;
   savedLow = 0.0;
   lookbackTotal = TA_CDLHIKKAKE_Lookback();
   if( startIdx < lookbackTotal )
   {
      startIdx = lookbackTotal;
   }
   if( startIdx > endIdx )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_SUCCESS;
   }
   cd = 0;
   patternResult = 0;
   i = startIdx - 3;
   while( i < startIdx )
   {
      if( inHigh[i - 1] < inHigh[i - 2] &&
          inLow[i - 1] > inLow[i - 2] &&
          ((inHigh[i] < inHigh[i - 1] &&
            inLow[i] < inLow[i - 1]) ||
           (inHigh[i] > inHigh[i - 1] &&
            inLow[i] > inLow[i - 1])) )
      {
         patternResult = 100 * ((inHigh[i] < inHigh[i - 1]) ? 1 : 0 - 1);
         savedHigh = inHigh[i - 1];
         savedLow = inLow[i - 1];
         cd = 4;
      } else if( cd > 0 &&
          ((patternResult > 0 &&
            inClose[i] > savedHigh) ||
           (patternResult < 0 &&
            inClose[i] < savedLow)) )
      {
         cd = 0;
      }
      if( cd > 0 )
      {
         cd -= 1;
      }
      i += 1;
   }
   i = startIdx;
   outIdx = 0;
   do
   {
      if( inHigh[i - 1] < inHigh[i - 2] &&
          inLow[i - 1] > inLow[i - 2] &&
          ((inHigh[i] < inHigh[i - 1] &&
            inLow[i] < inLow[i - 1]) ||
           (inHigh[i] > inHigh[i - 1] &&
            inLow[i] > inLow[i - 1])) )
      {
         patternResult = 100 * ((inHigh[i] < inHigh[i - 1]) ? 1 : 0 - 1);
         savedHigh = inHigh[i - 1];
         savedLow = inLow[i - 1];
         cd = 4;
         outInteger[outIdx++] = patternResult;
      } else if( cd > 0 &&
          ((patternResult > 0 &&
            inClose[i] > savedHigh) ||
           (patternResult < 0 &&
            inClose[i] < savedLow)) )
      {
         outInteger[outIdx++] = patternResult + 100 * ((patternResult > 0) ? 1 : 0 - 1);
         cd = 0;
      } else
      {
         outInteger[outIdx++] = 0;
      }
      if( cd > 0 )
      {
         cd -= 1;
      }
      i += 1;
   } while( i <= endIdx );
   *outNBElement= outIdx;
   *outBegIdx= startIdx;
   return TA_SUCCESS;
}

