   jI_Odd[1] = 0.0;
   jI_Odd[2] = 0.0;
   jI_Even[0] = 0.0;
   jI_Even[1] = 0.0;
   jI_Even[2] = 0.0;
   jI = 0.0;
   prev_jI_Odd = 0.0;
   prev_jI_Even = 0.0;
   prev_jI_input_Odd = 0.0;
   prev_jI_input_Even = 0.0;
   jQ_Odd[0] = 0.0;
   jQ_Odd[1] = 0.0;
   jQ_Odd[2] = 0.0;
   jQ_Even[0] = 0.0;
   jQ_Even[1] = 0.0;
   jQ_Even[2] = 0.0;
   jQ = 0.0;
   prev_jQ_Odd = 0.0;
   prev_jQ_Even = 0.0;
   prev_jQ_input_Odd = 0.0;
   prev_jQ_input_Even = 0.0;
   period = 0.0;
