      {
         outSine[outIdx] = sin(DCPhase * deg2Rad);
         outLeadSine[outIdx++] = sin((DCPhase + 45) * deg2Rad);
      }
      smoothPrice_Idx++;
      if( smoothPrice_Idx > maxIdx_smoothPrice ) smoothPrice_Idx = 0;
