/* ta_KAMA.c */
static inline TA_RetCode TA_KAMA( int    startIdx,
                               int    endIdx,
                               const double inReal[],
                               int optInTimePeriod,
                               int          *outBegIdx,
                               int          *outNBElement,
                               double        outReal[] )
{
   double constMax;
   double constDiff;
   double tempReal;
   double tempReal2;
   double sumROC1;
   double periodROC;
   double prevKAMA;
   int i;
   int today;
   int outIdx;
   int lookbackTotal;
   int trailingIdx;
   int nullRun;
   double trailingValue;
   if( (startIdx < 0) || (startIdx > TA_MAX_INDEX) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > TA_MAX_INDEX) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInTimePeriod == TA_INTEGER_DEFAULT )
      optInTimePeriod = 30;
   else if( (int)optInTimePeriod < 1 || (int)optInTimePeriod > 100000 )
      return TA_BAD_PARAM;
   if( !inReal )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   constMax = 2.0 / (30.0 + 1.0);
   constDiff = 2.0 / (2.0 + 1.0) - constMax;
   *outBegIdx= 0;
   *outNBElement= 0;
   if( optInTimePeriod == 1 )
   {
      lookbackTotal = TA_GLOBALS_UNSTABLE_PERIOD(TA_FUNC_UNST_KAMA,Kama);
      if( startIdx < lookbackTotal )
      {
         startIdx = lookbackTotal;
      }
      if( startIdx > endIdx )
      {
         return TA_SUCCESS;
      }
      *outBegIdx= startIdx;
      outIdx = 0;
      today = startIdx;
      while( today <= endIdx )
      {
         outReal[outIdx++] = inReal[today++];
      }
      *outNBElement= outIdx;
      return TA_SUCCESS;
   }
   lookbackTotal = optInTimePeriod + TA_GLOBALS_UNSTABLE_PERIOD(TA_FUNC_UNST_KAMA,Kama);
   if( startIdx < lookbackTotal )
   {
      startIdx = lookbackTotal;
   }
   if( startIdx > endIdx )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_SUCCESS;
   }
   sumROC1 = 0.0;
   nullRun = 0;
   today = startIdx - lookbackTotal;
   trailingIdx = today;
   i = optInTimePeriod;
   while( i-- > 0 )
   {
      tempReal = inReal[today++];
      tempReal -= inReal[today];
      sumROC1 += fabs(tempReal);
      if( tempReal == 0.0 )
      {
         nullRun += 1;
      } else
      {
         nullRun = 0;
      }
   }
   prevKAMA = inReal[today - 1];
   tempReal = inReal[today];
   tempReal2 = inReal[trailingIdx++];
   periodROC = tempReal - tempReal2;
   trailingValue = tempReal2;
   if( sumROC1 <= 0.0 || sumROC1 <= periodROC )
   {
      tempReal = 1.0;
   } else
   {
      tempReal = fabs(periodROC / sumROC1);
      if( tempReal > 1.0 )
      {
         tempReal = 1.0;
      }
   }
   tempReal = fma(tempReal, constDiff, constMax);
   tempReal *= tempReal;
   prevKAMA = fma(inReal[today++] - prevKAMA, tempReal, prevKAMA);
   while( today <= startIdx )
   {
      tempReal = inReal[today];
      tempReal2 = inReal[trailingIdx++];
      periodROC = tempReal - tempReal2;
      sumROC1 -= fabs(trailingValue - tempReal2);
      sumROC1 += fabs(tempReal - inReal[today - 1]);
      if( tempReal - inReal[today - 1] == 0.0 )
      {
         nullRun += 1;
      } else
      {
         nullRun = 0;
      }
      if( nullRun >= optInTimePeriod )
      {
         nullRun = optInTimePeriod;
         sumROC1 = 0.0;
      }
      trailingValue = tempReal2;
      if( sumROC1 <= 0.0 || sumROC1 <= periodROC )
      {
         tempReal = 1.0;
      } else
      {
         tempReal = fabs(periodROC / sumROC1);
         if( tempReal > 1.0 )
         {
            tempReal = 1.0;
         }
      }
      tempReal = fma(tempReal, constDiff, constMax);
      tempReal *= tempReal;
      prevKAMA = fma(inReal[today++] - prevKAMA, tempReal, prevKAMA);
   }
   outReal[0] = prevKAMA;
   outIdx = 1;
   *outBegIdx= today - 1;
   while( today <= endIdx )
   {
      tempReal = inReal[today];
      tempReal2 = inReal[trailingIdx++];
      periodROC = tempReal - tempReal2;
      sumROC1 -= fabs(trailingValue - tempReal2);
      sumROC1 += fabs(tempReal - inReal[today - 1]);
      if( tempReal - inReal[today - 1] == 0.0 )
      {
         nullRun += 1;
      } else
      {
         nullRun = 0;
      }
      if( nullRun >= optInTimePeriod )
      {
         nullRun = optInTimePeriod;
         sumROC1 = 0.0;
      }
      trailingValue = tempReal2;
      if( sumROC1 <= 0.0 || sumROC1 <= periodROC )
      {
         tempReal = 1.0;
      } else
      {
         tempReal = fabs(periodROC / sumROC1);
         if( tempReal > 1.0 )
         {
            tempReal = 1.0;
         }
      }
      tempReal = fma(tempReal, constDiff, constMax);
      tempReal *= tempReal;
      prevKAMA = fma(inReal[today++] - prevKAMA, tempReal, prevKAMA);
      outReal[outIdx++] = prevKAMA;
   }
   *outNBElement= outIdx;
   return TA_SUCCESS;
}

/* ta_KAMA.c */
static inline int TA_KAMA_Lookback( int optInTimePeriod )
{
   if( (int)optInTimePeriod == TA_INTEGER_DEFAULT )
      optInTimePeriod = 30;
   else if( (int)optInTimePeriod < 1 || (int)optInTimePeriod > 100000 )
      return -1;
   if( optInTimePeriod == 1 )
   {
      return TA_GLOBALS_UNSTABLE_PERIOD(TA_FUNC_UNST_KAMA,Kama);
   }
   return optInTimePeriod + TA_GLOBALS_UNSTABLE_PERIOD(TA_FUNC_UNST_KAMA,Kama);
}

/* ta_LINEARREG.c */
static inline TA_RetCode TA_LINEARREG( int    startIdx,
                                    int    endIdx,
                                    const double inReal[],
                                    int optInTimePeriod,
                                    int          *outBegIdx,
                                    int          *outNBElement,
                                    double        outReal[] )
{
   int outIdx;
   int today;
   int lookbackTotal;
   int trailingIdx;
   double SumX;
   double SumXY;
   double SumY;
   double SumXSqr;
   double Divisor;
   double m;
   double b;
   int i;
   int j;
   int windowStart;
   int barsSinceReseed;
   double tempValue1;
   double tempValue2;
   double trailingValue;
   double weightedTrailing;
   double sumAbs;
   if( (startIdx < 0) || (startIdx > TA_MAX_INDEX) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > TA_MAX_INDEX) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInTimePeriod == TA_INTEGER_DEFAULT )
      optInTimePeriod = 14;
   else if( (int)optInTimePeriod < 2 || (int)optInTimePeriod > 100000 )
      return TA_BAD_PARAM;
   if( !inReal )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   lookbackTotal = TA_LINEARREG_Lookback(optInTimePeriod);
   if( startIdx < lookbackTotal )
   {
      startIdx = lookbackTotal;
   }
   if( startIdx > endIdx )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_SUCCESS;
   }
   outIdx = 0;
   today = startIdx;
   trailingIdx = startIdx - lookbackTotal;
   SumX = (double)optInTimePeriod * (optInTimePeriod - 1) * 0.5;
   SumXSqr = (double)optInTimePeriod * (optInTimePeriod - 1) * (2 * optInTimePeriod - 1) / 6.0;
   Divisor = SumX * SumX - optInTimePeriod * SumXSqr;
   SumXY = 0;
   SumY = 0;
   sumAbs = 0;
   for( i = optInTimePeriod; i-- != 0;  )
   {
      tempValue1 = inReal[today - i];
      SumY += tempValue1;
      SumXY += (double)i * tempValue1;
      sumAbs += fabs(tempValue1);
   }
   m = (optInTimePeriod * SumXY - SumX * SumY) / Divisor;
   b = (SumY - m * SumX) / (double)optInTimePeriod;
   barsSinceReseed = 32 * optInTimePeriod;
   trailingValue = inReal[trailingIdx];
   trailingIdx += 1;
   outReal[outIdx++] = fma(m, (double)(optInTimePeriod - 1), b);
   today += 1;
   while( today <= endIdx )
   {
      weightedTrailing = (double)optInTimePeriod * trailingValue;
      SumXY = SumXY + SumY - weightedTrailing;
      SumY = SumY - trailingValue + inReal[today];
      sumAbs = sumAbs - fabs(trailingValue) + fabs(inReal[today]);
      barsSinceReseed -= 1;
      if( barsSinceReseed <= 0 || fabs(weightedTrailing) > 100.0 * sumAbs )
      {
         barsSinceReseed = 32 * optInTimePeriod;
         windowStart = today - lookbackTotal;
         SumY = 0;
         SumXY = 0;
         sumAbs = 0;
         tempValue2 = (double)lookbackTotal;
         for( j = windowStart; j <= today; j += 1 )
         {
            tempValue1 = inReal[j];
            SumY += tempValue1;
            SumXY += tempValue2 * tempValue1;
            sumAbs += fabs(tempValue1);
            tempValue2 -= 1.0;
         }
      }
      m = (optInTimePeriod * SumXY - SumX * SumY) / Divisor;
      b = (SumY - m * SumX) / (double)optInTimePeriod;
      trailingValue = inReal[trailingIdx];
      trailingIdx += 1;
      outReal[outIdx++] = fma(m, (double)(optInTimePeriod - 1), b);
      today += 1;
   }
   *outBegIdx= startIdx;
   *outNBElement= outIdx;
   return TA_SUCCESS;
}

/* ta_LINEARREG.c */
static inline int TA_LINEARREG_Lookback( int optInTimePeriod )
{
   if( (int)optInTimePeriod == TA_INTEGER_DEFAULT )
      optInTimePeriod = 14;
   else if( (int)optInTimePeriod < 2 || (int)optInTimePeriod > 100000 )
      return -1;
   return optInTimePeriod - 1;
}

