/* ta_MA.c */
static inline TA_RetCode TA_MA( int    startIdx,
                             int    endIdx,
                             const double inReal[],
                             int optInTimePeriod,
                             TA_MAType optInMAType,
                             int          *outBegIdx,
                             int          *outNBElement,
                             double        outReal[] )
{
   TA_RetCode retCode;
   int nbElement;
   int outIdx;
   int todayIdx;
   if( (startIdx < 0) || (startIdx > TA_MAX_INDEX) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > TA_MAX_INDEX) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInTimePeriod == TA_INTEGER_DEFAULT )
      optInTimePeriod = 30;
   else if( (int)optInTimePeriod < 1 || (int)optInTimePeriod > 100000 )
      return TA_BAD_PARAM;
   if( (int)optInMAType == TA_INTEGER_DEFAULT || optInMAType == TA_MAType_DEFAULT )
      optInMAType = 0;
   else if( (int)optInMAType < TA_MATYPE_MIN || (int)optInMAType > TA_MATYPE_MAX )
      return TA_BAD_PARAM;
   if( !inReal )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   if( TA_MA_Lookback(optInTimePeriod,optInMAType) > endIdx )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_SUCCESS;
   }
   if( optInTimePeriod == 1 || optInMAType == TA_MAType_DISABLED )
   {
      nbElement = endIdx - startIdx + 1;
      *outNBElement= nbElement;
      for( todayIdx = startIdx, outIdx = 0; outIdx < nbElement; outIdx += 1, todayIdx += 1 )
      {
         outReal[outIdx] = inReal[todayIdx];
      }
      *outBegIdx= startIdx;
      return TA_SUCCESS;
   }
   switch( optInMAType )
   {
   case TA_MAType_SMA:
      retCode = TA_SMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_EMA:
      retCode = TA_EMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_WMA:
      retCode = TA_WMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_DEMA:
      retCode = TA_DEMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_TEMA:
      retCode = TA_TEMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_TRIMA:
      retCode = TA_TRIMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_KAMA:
      retCode = TA_KAMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_MAMA:
      retCode = TA_MAMA(startIdx,endIdx,inReal,0.5,0.05,outBegIdx,outNBElement,outReal,NULL);
      break;
   case TA_MAType_T3:
      retCode = TA_T3(startIdx,endIdx,inReal,optInTimePeriod,0.7,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_HMA:
      retCode = TA_HMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_ZLEMA:
      retCode = TA_ZLEMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_RMA:
      retCode = TA_RMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   default:
      retCode = TA_BAD_PARAM;
      break;
   }
   return retCode;
}

/* ta_MA.c */
static inline int TA_MA_Lookback( int optInTimePeriod, TA_MAType optInMAType )
{
   int retValue;
   if( (int)optInTimePeriod == TA_INTEGER_DEFAULT )
      optInTimePeriod = 30;
   else if( (int)optInTimePeriod < 1 || (int)optInTimePeriod > 100000 )
      return -1;
   if( (int)optInMAType == TA_INTEGER_DEFAULT || optInMAType == TA_MAType_DEFAULT )
      optInMAType = 0;
   else if( (int)optInMAType < TA_MATYPE_MIN || (int)optInMAType > TA_MATYPE_MAX )
      return -1;
   if( optInTimePeriod <= 1 || optInMAType == TA_MAType_DISABLED )
   {
      return 0;
   }
   switch( optInMAType )
   {
   case TA_MAType_SMA:
      retValue = TA_SMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_EMA:
      retValue = TA_EMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_WMA:
      retValue = TA_WMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_DEMA:
      retValue = TA_DEMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_TEMA:
      retValue = TA_TEMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_TRIMA:
      retValue = TA_TRIMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_KAMA:
      retValue = TA_KAMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_MAMA:
      retValue = TA_MAMA_Lookback(0.5,0.05);
      break;
   case TA_MAType_T3:
      retValue = TA_T3_Lookback(optInTimePeriod,0.7);
      break;
   case TA_MAType_HMA:
      retValue = TA_HMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_ZLEMA:
      retValue = TA_ZLEMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_RMA:
      retValue = TA_RMA_Lookback(optInTimePeriod);
      break;
   default:
      retValue = 0;
      break;
   }
   return retValue;
}

/* ta_MACD.c */
static inline TA_RetCode TA_MACD( int    startIdx,
                               int    endIdx,
                               const double inReal[],
                               int optInFastPeriod,
                               int optInSlowPeriod,
                               int optInSignalPeriod,
                               int          *outBegIdx,
                               int          *outNBElement,
                               double        outMACD[],
                               double        outMACDSignal[],
                               double        outMACDHist[] )
{
   double prevFast;
   double prevSlow;
   double prevSignal;
   double macdValue;
   double tempReal;
   double slowK;
   double fastK;
   double signalK;
   int i;
   int today;
   int outIdx;
   int tempInteger;
   int lookbackTotal;
   int lookbackSignal;
   if( (startIdx < 0) || (startIdx > TA_MAX_INDEX) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > TA_MAX_INDEX) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInFastPeriod == TA_INTEGER_DEFAULT )
      optInFastPeriod = 12;
   else if( (int)optInFastPeriod < 2 || (int)optInFastPeriod > 100000 )
      return TA_BAD_PARAM;
   if( (int)optInSlowPeriod == TA_INTEGER_DEFAULT )
      optInSlowPeriod = 26;
   else if( (int)optInSlowPeriod < 2 || (int)optInSlowPeriod > 100000 )
      return TA_BAD_PARAM;
   if( (int)optInSignalPeriod == TA_INTEGER_DEFAULT )
      optInSignalPeriod = 9;
   else if( (int)optInSignalPeriod < 1 || (int)optInSignalPeriod > 100000 )
      return TA_BAD_PARAM;
   if( !inReal )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outMACD )
      return TA_BAD_PARAM;
   if( !outMACDSignal )
      return TA_BAD_PARAM;
   if( !outMACDHist )
      return TA_BAD_PARAM;
   if( outMACD == outMACDSignal || outMACD == outMACDHist || outMACDSignal == outMACDHist )
      return TA_BAD_PARAM;
   if( optInSlowPeriod < optInFastPeriod )
   {
      tempInteger = optInSlowPeriod;
      optInSlowPeriod = optInFastPeriod;
      optInFastPeriod = tempInteger;
   }
   if( optInSlowPeriod == 0 )
   {
      optInSlowPeriod = 26;
      slowK = 0.075;
   } else
   {
      slowK = 2.0 / (double)(optInSlowPeriod + 1);
   }
   if( optInFastPeriod == 0 )
   {
      optInFastPeriod = 12;
      fastK = 0.15;
   } else
   {
      fastK = 2.0 / (double)(optInFastPeriod + 1);
   }
   signalK = 2.0 / (double)(optInSignalPeriod + 1);
   lookbackSignal = TA_EMA_Lookback(optInSignalPeriod);
   lookbackTotal = lookbackSignal;
   lookbackTotal += TA_EMA_Lookback(optInSlowPeriod);
   if( startIdx < lookbackTotal )
   {
      startIdx = lookbackTotal;
   }
   if( startIdx > endIdx )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_SUCCESS;
   }
   today = startIdx - lookbackTotal;
   tempReal = 0.0;
   i = optInSlowPeriod - optInFastPeriod;
   while( i-- > 0 )
   {
      tempReal += inReal[today++];
   }
   prevFast = 0.0;
   i = optInFastPeriod;
   while( i-- > 0 )
   {
      prevFast += inReal[today];
      tempReal += inReal[today++];
   }
   prevSlow = tempReal / optInSlowPeriod;
   prevFast = prevFast / optInFastPeriod;
   while( today <= startIdx - lookbackSignal )
   {
      tempReal = inReal[today++];
      prevFast = fma(tempReal - prevFast, fastK, prevFast);
      prevSlow = fma(tempReal - prevSlow, slowK, prevSlow);
   }
   macdValue = prevFast - prevSlow;
   prevSignal = 0.0;
   prevSignal += macdValue;
   i = optInSignalPeriod - 1;
   while( i-- > 0 )
   {
      tempReal = inReal[today++];
      prevFast = fma(tempReal - prevFast, fastK, prevFast);
      prevSlow = fma(tempReal - prevSlow, slowK, prevSlow);
      macdValue = prevFast - prevSlow;
      prevSignal += macdValue;
   }
   prevSignal = prevSignal / optInSignalPeriod;
   while( today <= startIdx )
   {
      tempReal = inReal[today++];
      prevFast = fma(tempReal - prevFast, fastK, prevFast);
      prevSlow = fma(tempReal - prevSlow, slowK, prevSlow);
      macdValue = prevFast - prevSlow;
      if( optInSignalPeriod == 1 )
      {
         prevSignal = macdValue;
      } else
      {
         prevSignal = fma(macdValue - prevSignal, signalK, prevSignal);
      }
   }
   outMACD[0] = macdValue;
   outMACDSignal[0] = prevSignal;
   outMACDHist[0] = macdValue - prevSignal;
   outIdx = 1;
   while( today <= endIdx )
   {
      tempReal = inReal[today++];
      prevFast = fma(tempReal - prevFast, fastK, prevFast);
      prevSlow = fma(tempReal - prevSlow, slowK, prevSlow);
      macdValue = prevFast - prevSlow;
      if( optInSignalPeriod == 1 )
      {
         prevSignal = macdValue;
      } else
      {
         prevSignal = fma(macdValue - prevSignal, signalK, prevSignal);
      }
      outMACD[outIdx] = macdValue;
      outMACDSignal[outIdx] = prevSignal;
      outMACDHist[outIdx] = macdValue - prevSignal;
      outIdx += 1;
   }
   *outBegIdx= startIdx;
   *outNBElement= outIdx;
   return TA_SUCCESS;
}

/* ta_MACD.c */
static inline int TA_MACD_Lookback( int optInFastPeriod, int optInSlowPeriod, int optInSignalPeriod )
{
   int tempInteger;
   if( (int)optInFastPeriod == TA_INTEGER_DEFAULT )
      optInFastPeriod = 12;
   else if( (int)optInFastPeriod < 2 || (int)optInFastPeriod > 100000 )
      return -1;
   if( (int)optInSlowPeriod == TA_INTEGER_DEFAULT )
      optInSlowPeriod = 26;
   else if( (int)optInSlowPeriod < 2 || (int)optInSlowPeriod > 100000 )
      return -1;
   if( (int)optInSignalPeriod == TA_INTEGER_DEFAULT )
      optInSignalPeriod = 9;
   else if( (int)optInSignalPeriod < 1 || (int)optInSignalPeriod > 100000 )
      return -1;
   if( optInSlowPeriod < optInFastPeriod )
   {
      tempInteger = optInSlowPeriod;
      optInSlowPeriod = optInFastPeriod;
      optInFastPeriod = tempInteger;
   }
   return TA_EMA_Lookback(optInSlowPeriod) + TA_EMA_Lookback(optInSignalPeriod);
}

/* ta_MAMA.c */
static inline TA_RetCode TA_MAMA( int    startIdx,
                               int    endIdx,
                               const double inReal[],
                               double optInFastLimit,
                               double optInSlowLimit,
                               int          *outBegIdx,
                               int          *outNBElement,
                               double        outMAMA[],
                               double        outFAMA[] )
{
   int outIdx;
   int i;
   int lookbackTotal;
   int today;
   double tempReal;
   double tempReal2;
   double adjustedPrevPeriod;
   double period;
   int trailingWMAIdx;
   double periodWMASum;
   double periodWMASub;
   double trailingWMAValue;
   double smoothedValue;
   double a;
   double b;
   double hilbertTempReal;
   int hilbertIdx;
   double detrender_Odd[3];
   double detrender_Even[3];
   double detrender;
   double prev_detrender_Odd;
   double prev_detrender_Even;
   double prev_detrender_input_Odd;
   double prev_detrender_input_Even;
   double Q1_Odd[3];
   double Q1_Even[3];
   double Q1;
   double prev_Q1_Odd;
   double prev_Q1_Even;
   double prev_Q1_input_Odd;
   double prev_Q1_input_Even;
   double jI_Odd[3];
   double jI_Even[3];
   double jI;
   double prev_jI_Odd;
   double prev_jI_Even;
   double prev_jI_input_Odd;
   double prev_jI_input_Even;
   double jQ_Odd[3];
   double jQ_Even[3];
   double jQ;
   double prev_jQ_Odd;
   double prev_jQ_Even;
   double prev_jQ_input_Odd;
   double prev_jQ_input_Even;
   double Q2;
   double I2;
   double prevQ2;
   double prevI2;
   double Re;
   double Im;
   double I1ForOddPrev2;
   double I1ForOddPrev3;
   double I1ForEvenPrev2;
   double I1ForEvenPrev3;
   double rad2Deg;
   double mama;
   double fama;
   double todayValue;
   double prevPhase;
   if( (startIdx < 0) || (startIdx > TA_MAX_INDEX) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > TA_MAX_INDEX) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( optInFastLimit == TA_REAL_DEFAULT )
      optInFastLimit = 0.5;
   else if( !(optInFastLimit >= 1e-2 && optInFastLimit <= 9.9e-1) )
      return TA_BAD_PARAM;
   if( optInSlowLimit == TA_REAL_DEFAULT )
      optInSlowLimit = 0.05;
   else if( !(optInSlowLimit >= 1e-2 && optInSlowLimit <= 9.9e-1) )
      return TA_BAD_PARAM;
   if( !inReal )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outMAMA )
      return TA_BAD_PARAM;
   if( outFAMA != NULL && outMAMA == outFAMA )
      return TA_BAD_PARAM;
   a = 0.0962;
   b = 0.5769;
   rad2Deg = 180.0 / (4.0 * atan(1));
   lookbackTotal = 32 + TA_GLOBALS_UNSTABLE_PERIOD(TA_FUNC_UNST_MAMA,Mama);
   if( startIdx < lookbackTotal )
   {
      startIdx = lookbackTotal;
   }
   if( startIdx > endIdx )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_SUCCESS;
   }
   *outBegIdx= startIdx;
   trailingWMAIdx = startIdx - lookbackTotal;
   today = trailingWMAIdx;
   tempReal = inReal[today++];
   periodWMASub = tempReal;
   periodWMASum = tempReal;
   tempReal = inReal[today++];
   periodWMASub += tempReal;
   periodWMASum += tempReal * 2.0;
   tempReal = inReal[today++];
   periodWMASub += tempReal;
   periodWMASum += tempReal * 3.0;
   trailingWMAValue = 0.0;
   i = 9;
   do
   {
      tempReal = inReal[today++];
      periodWMASub += tempReal;
      periodWMASub -= trailingWMAValue;
      periodWMASum += tempReal * 4.0;
      trailingWMAValue = inReal[trailingWMAIdx++];
      smoothedValue = periodWMASum * 0.1;
      periodWMASum -= periodWMASub;
   } while( --i != 0 );
   hilbertIdx = 0;
   detrender_Odd[0] = 0.0;
   detrender_Odd[1] = 0.0;
   detrender_Odd[2] = 0.0;
   detrender_Even[0] = 0.0;
   detrender_Even[1] = 0.0;
   detrender_Even[2] = 0.0;
   detrender = 0.0;
   prev_detrender_Odd = 0.0;
   prev_detrender_Even = 0.0;
   prev_detrender_input_Odd = 0.0;
   prev_detrender_input_Even = 0.0;
   Q1_Odd[0] = 0.0;
   Q1_Odd[1] = 0.0;
   Q1_Odd[2] = 0.0;
   Q1_Even[0] = 0.0;
   Q1_Even[1] = 0.0;
   Q1_Even[2] = 0.0;
   Q1 = 0.0;
   prev_Q1_Odd = 0.0;
   prev_Q1_Even = 0.0;
   prev_Q1_input_Odd = 0.0;
   prev_Q1_input_Even = 0.0;
   jI_Odd[0] = 0.0;
   jI_Odd[1] = 0.0;
   jI_Odd[2] = 0.0;
   jI_Even[0] = 0.0;
   jI_Even[1] = 0.0;
   jI_Even[2] = 0.0;
   jI = 0.0;
   prev_jI_Odd = 0.0;
   prev_jI_Even = 0.0;
   prev_jI_input_Odd = 0.0;
   prev_jI_input_Even = 0.0;
   jQ_Odd[0] = 0.0;
   jQ_Odd[1] = 0.0;
   jQ_Odd[2] = 0.0;
   jQ_Even[0] = 0.0;
   jQ_Even[1] = 0.0;
   jQ_Even[2] = 0.0;
   jQ = 0.0;
   prev_jQ_Odd = 0.0;
   prev_jQ_Even = 0.0;
   prev_jQ_input_Odd = 0.0;
   prev_jQ_input_Even = 0.0;
   period = 0.0;
   outIdx = 0;
   prevQ2 = 0.0;
   prevI2 = prevQ2;
   Im = 0.0;
   Re = Im;
   fama = 0.0;
   mama = fama;
   I1ForEvenPrev3 = 0.0;
   I1ForOddPrev3 = I1ForEvenPrev3;
   I1ForEvenPrev2 = 0.0;
   I1ForOddPrev2 = I1ForEvenPrev2;
   prevPhase = 0.0;
   while( today <= endIdx )
   {
      adjustedPrevPeriod = fma(0.075, period, 0.54);
      todayValue = inReal[today];
      periodWMASub += todayValue;
      periodWMASub -= trailingWMAValue;
      periodWMASum += todayValue * 4.0;
      trailingWMAValue = inReal[trailingWMAIdx++];
      smoothedValue = periodWMASum * 0.1;
      periodWMASum -= periodWMASub;
      if( today % 2 == 0 )
      {
         hilbertTempReal = a * smoothedValue;
         detrender = 0 - detrender_Even[hilbertIdx];
         detrender_Even[hilbertIdx] = hilbertTempReal;
         detrender += hilbertTempReal;
         detrender -= prev_detrender_Even;
         prev_detrender_Even = b * prev_detrender_input_Even;
         detrender += prev_detrender_Even;
         prev_detrender_input_Even = smoothedValue;
         detrender *= adjustedPrevPeriod;
         hilbertTempReal = a * detrender;
         Q1 = 0 - Q1_Even[hilbertIdx];
         Q1_Even[hilbertIdx] = hilbertTempReal;
         Q1 += hilbertTempReal;
         Q1 -= prev_Q1_Even;
         prev_Q1_Even = b * prev_Q1_input_Even;
         Q1 += prev_Q1_Even;
         prev_Q1_input_Even = detrender;
         Q1 *= adjustedPrevPeriod;
         hilbertTempReal = a * I1ForEvenPrev3;
         jI = 0 - jI_Even[hilbertIdx];
         jI_Even[hilbertIdx] = hilbertTempReal;
         jI += hilbertTempReal;
         jI -= prev_jI_Even;
         prev_jI_Even = b * prev_jI_input_Even;
         jI += prev_jI_Even;
         prev_jI_input_Even = I1ForEvenPrev3;
         jI *= adjustedPrevPeriod;
         hilbertTempReal = a * Q1;
         jQ = 0 - jQ_Even[hilbertIdx];
         jQ_Even[hilbertIdx] = hilbertTempReal;
         jQ += hilbertTempReal;
         jQ -= prev_jQ_Even;
         prev_jQ_Even = b * prev_jQ_input_Even;
         jQ += prev_jQ_Even;
         prev_jQ_input_Even = Q1;
         jQ *= adjustedPrevPeriod;
         if( ++hilbertIdx == 3 )
         {
            hilbertIdx = 0;
         }
         Q2 = fma(0.2, Q1 + jI, 0.8 * prevQ2);
         I2 = fma(0.2, I1ForEvenPrev3 - jQ, 0.8 * prevI2);
         I1ForOddPrev3 = I1ForOddPrev2;
         I1ForOddPrev2 = detrender;
         if( I1ForEvenPrev3 != 0.0 )
         {
            tempReal2 = atan(Q1 / I1ForEvenPrev3) * rad2Deg;
         } else
         {
            tempReal2 = 0.0;
         }
      } else
      {
         hilbertTempReal = a * smoothedValue;
         detrender = 0 - detrender_Odd[hilbertIdx];
         detrender_Odd[hilbertIdx] = hilbertTempReal;
         detrender += hilbertTempReal;
         detrender -= prev_detrender_Odd;
         prev_detrender_Odd = b * prev_detrender_input_Odd;
         detrender += prev_detrender_Odd;
         prev_detrender_input_Odd = smoothedValue;
         detrender *= adjustedPrevPeriod;
         hilbertTempReal = a * detrender;
         Q1 = 0 - Q1_Odd[hilbertIdx];
         Q1_Odd[hilbertIdx] = hilbertTempReal;
         Q1 += hilbertTempReal;
         Q1 -= prev_Q1_Odd;
         prev_Q1_Odd = b * prev_Q1_input_Odd;
         Q1 += prev_Q1_Odd;
         prev_Q1_input_Odd = detrender;
         Q1 *= adjustedPrevPeriod;
         hilbertTempReal = a * I1ForOddPrev3;
         jI = 0 - jI_Odd[hilbertIdx];
         jI_Odd[hilbertIdx] = hilbertTempReal;
         jI += hilbertTempReal;
         jI -= prev_jI_Odd;
         prev_jI_Odd = b * prev_jI_input_Odd;
         jI += prev_jI_Odd;
         prev_jI_input_Odd = I1ForOddPrev3;
         jI *= adjustedPrevPeriod;
         hilbertTempReal = a * Q1;
         jQ = 0 - jQ_Odd[hilbertIdx];
         jQ_Odd[hilbertIdx] = hilbertTempReal;
         jQ += hilbertTempReal;
         jQ -= prev_jQ_Odd;
         prev_jQ_Odd = b * prev_jQ_input_Odd;
         jQ += prev_jQ_Odd;
         prev_jQ_input_Odd = Q1;
         jQ *= adjustedPrevPeriod;
         Q2 = fma(0.2, Q1 + jI, 0.8 * prevQ2);
         I2 = fma(0.2, I1ForOddPrev3 - jQ, 0.8 * prevI2);
         I1ForEvenPrev3 = I1ForEvenPrev2;
         I1ForEvenPrev2 = detrender;
         if( I1ForOddPrev3 != 0.0 )
         {
            tempReal2 = atan(Q1 / I1ForOddPrev3) * rad2Deg;
         } else
         {
            tempReal2 = 0.0;
         }
      }
      tempReal = prevPhase - tempReal2;
      prevPhase = tempReal2;
      if( tempReal < 1.0 )
      {
         tempReal = 1.0;
      }
      if( tempReal > 1.0 )
      {
         tempReal = optInFastLimit / tempReal;
         if( tempReal < optInSlowLimit )
         {
            tempReal = optInSlowLimit;
         }
      } else
      {
         tempReal = optInFastLimit;
      }
      mama = fma(1 - tempReal, mama, tempReal * todayValue);
      tempReal *= 0.5;
      fama = fma(1 - tempReal, fama, tempReal * mama);
      if( today >= startIdx )
      {
         if( outFAMA != NULL )
            outFAMA[outIdx] = fama;
         outMAMA[outIdx++] = mama;
      }
      Re = fma(0.8, Re, 0.2 * (fma(I2, prevI2, Q2 * prevQ2)));
      Im = fma(0.8, Im, 0.2 * (I2 * prevQ2 - Q2 * prevI2));
      prevQ2 = Q2;
      prevI2 = I2;
      tempReal = period;
      if( Im != 0.0 && Re != 0.0 )
      {
         period = 360.0 / (atan(Im / Re) * rad2Deg);
      }
      tempReal2 = 1.5 * tempReal;
      if( period > tempReal2 )
      {
         period = tempReal2;
      }
      tempReal2 = 0.67 * tempReal;
      if( period < tempReal2 )
      {
         period = tempReal2;
      }
      if( period < 6 )
      {
         period = 6;
      } else if( period > 50 )
      {
         period = 50;
      }
      period = fma(0.2, period, 0.8 * tempReal);
      today += 1;
   }
   *outNBElement= outIdx;
   return TA_SUCCESS;
}

/* ta_MAMA.c */
static inline int TA_MAMA_Lookback( double optInFastLimit, double optInSlowLimit )
{
   if( optInFastLimit == TA_REAL_DEFAULT )
      optInFastLimit = 0.5;
   else if( !(optInFastLimit >= 1e-2 && optInFastLimit <= 9.9e-1) )
      return -1;
   if( optInSlowLimit == TA_REAL_DEFAULT )
      optInSlowLimit = 0.05;
   else if( !(optInSlowLimit >= 1e-2 && optInSlowLimit <= 9.9e-1) )
      return -1;
   return 32 + TA_GLOBALS_UNSTABLE_PERIOD(TA_FUNC_UNST_MAMA,Mama);
}

/* ta_MEDPRICE.c */
static inline TA_RetCode TA_MEDPRICE( int    startIdx,
                                   int    endIdx,
                                   const double inHigh[],
                                   const double inLow[],
                                   int          *outBegIdx,
                                   int          *outNBElement,
                                   double        outReal[] )
{
   int outIdx;
   int i;
   if( (startIdx < 0) || (startIdx > TA_MAX_INDEX) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > TA_MAX_INDEX) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( !inHigh )
      return TA_BAD_PARAM;
   if( !inLow )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   outIdx = 0;
   for( i = startIdx; i <= endIdx; i += 1 )
   {
      outReal[outIdx++] = (inHigh[i] + inLow[i]) / 2.0;
   }
   *outNBElement= outIdx;
   *outBegIdx= startIdx;
   return TA_SUCCESS;
}

