/* ta_T3.c */
static inline TA_RetCode TA_T3( int    startIdx,
                             int    endIdx,
                             const double inReal[],
                             int optInTimePeriod,
                             double optInVFactor,
                             int          *outBegIdx,
                             int          *outNBElement,
                             double        outReal[] )
{
   int outIdx;
   int lookbackTotal;
   int today;
   int i;
   double k;
   double one_minus_k;
   double e1;
   double e2;
   double e3;
   double e4;
   double e5;
   double e6;
   double c1;
   double c2;
   double c3;
   double c4;
   double tempReal;
   if( (startIdx < 0) || (startIdx > TA_MAX_INDEX) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > TA_MAX_INDEX) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInTimePeriod == TA_INTEGER_DEFAULT )
      optInTimePeriod = 5;
   else if( (int)optInTimePeriod < 1 || (int)optInTimePeriod > 100000 )
      return TA_BAD_PARAM;
   if( optInVFactor == TA_REAL_DEFAULT )
      optInVFactor = 0.7;
   else if( !(optInVFactor >= 0e0 && optInVFactor <= 1e0) )
      return TA_BAD_PARAM;
   if( !inReal )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   lookbackTotal = 6 * (optInTimePeriod - 1) + TA_GLOBALS_UNSTABLE_PERIOD(TA_FUNC_UNST_T3,T3);
   if( startIdx <= lookbackTotal )
   {
      startIdx = lookbackTotal;
   }
   if( startIdx > endIdx )
   {
      *outNBElement= 0;
      *outBegIdx= 0;
      return TA_SUCCESS;
   }
   if( optInTimePeriod == 1 )
   {
      *outBegIdx= startIdx;
      outIdx = 0;
      today = startIdx;
      while( today <= endIdx )
      {
         outReal[outIdx++] = inReal[today++];
      }
      *outNBElement= outIdx;
      return TA_SUCCESS;
   }
   *outBegIdx= startIdx;
   today = startIdx - lookbackTotal;
   k = 2.0 / (optInTimePeriod + 1.0);
   one_minus_k = 1.0 - k;
   tempReal = inReal[today++];
   for( i = optInTimePeriod - 1; i > 0; i -= 1 )
   {
      tempReal += inReal[today++];
   }
   e1 = tempReal / optInTimePeriod;
   tempReal = e1;
   for( i = optInTimePeriod - 1; i > 0; i -= 1 )
   {
      e1 = fma(one_minus_k, e1, k * inReal[today++]);
      tempReal += e1;
   }
   e2 = tempReal / optInTimePeriod;
   tempReal = e2;
   for( i = optInTimePeriod - 1; i > 0; i -= 1 )
   {
      e1 = fma(one_minus_k, e1, k * inReal[today++]);
      e2 = fma(one_minus_k, e2, k * e1);
      tempReal += e2;
   }
   e3 = tempReal / optInTimePeriod;
   tempReal = e3;
   for( i = optInTimePeriod - 1; i > 0; i -= 1 )
   {
      e1 = fma(one_minus_k, e1, k * inReal[today++]);
      e2 = fma(one_minus_k, e2, k * e1);
      e3 = fma(one_minus_k, e3, k * e2);
      tempReal += e3;
   }
   e4 = tempReal / optInTimePeriod;
   tempReal = e4;
   for( i = optInTimePeriod - 1; i > 0; i -= 1 )
   {
      e1 = fma(one_minus_k, e1, k * inReal[today++]);
      e2 = fma(one_minus_k, e2, k * e1);
      e3 = fma(one_minus_k, e3, k * e2);
      e4 = fma(one_minus_k, e4, k * e3);
      tempReal += e4;
   }
   e5 = tempReal / optInTimePeriod;
   tempReal = e5;
   for( i = optInTimePeriod - 1; i > 0; i -= 1 )
   {
      e1 = fma(one_minus_k, e1, k * inReal[today++]);
      e2 = fma(one_minus_k, e2, k * e1);
      e3 = fma(one_minus_k, e3, k * e2);
      e4 = fma(one_minus_k, e4, k * e3);
      e5 = fma(one_minus_k, e5, k * e4);
      tempReal += e5;
   }
   e6 = tempReal / optInTimePeriod;
   while( today <= startIdx )
   {
      e1 = fma(one_minus_k, e1, k * inReal[today++]);
      e2 = fma(one_minus_k, e2, k * e1);
      e3 = fma(one_minus_k, e3, k * e2);
      e4 = fma(one_minus_k, e4, k * e3);
      e5 = fma(one_minus_k, e5, k * e4);
      e6 = fma(one_minus_k, e6, k * e5);
   }
   tempReal = optInVFactor * optInVFactor;
   c1 = 0 - tempReal * optInVFactor;
   c2 = 3.0 * (tempReal - c1);
   c3 = (0 - 6.0) * tempReal - 3.0 * (optInVFactor - c1);
   c4 = fma(3.0, tempReal, fma(3.0, optInVFactor, 1.0) - c1);
   outIdx = 0;
   outReal[outIdx++] = fma(c4, e3, fma(c3, e4, fma(c1, e6, c2 * e5)));
   while( today <= endIdx )
   {
      e1 = fma(one_minus_k, e1, k * inReal[today++]);
      e2 = fma(one_minus_k, e2, k * e1);
      e3 = fma(one_minus_k, e3, k * e2);
      e4 = fma(one_minus_k, e4, k * e3);
      e5 = fma(one_minus_k, e5, k * e4);
      e6 = fma(one_minus_k, e6, k * e5);
      outReal[outIdx++] = fma(c4, e3, fma(c3, e4, fma(c1, e6, c2 * e5)));
   }
   *outNBElement= outIdx;
   return TA_SUCCESS;
}

/* ta_T3.c */
static inline int TA_T3_Lookback( int optInTimePeriod, double optInVFactor )
{
   if( (int)optInTimePeriod == TA_INTEGER_DEFAULT )
      optInTimePeriod = 5;
   else if( (int)optInTimePeriod < 1 || (int)optInTimePeriod > 100000 )
      return -1;
   if( optInVFactor == TA_REAL_DEFAULT )
      optInVFactor = 0.7;
   else if( !(optInVFactor >= 0e0 && optInVFactor <= 1e0) )
      return -1;
   return 6 * (optInTimePeriod - 1) + TA_GLOBALS_UNSTABLE_PERIOD(TA_FUNC_UNST_T3,T3);
}

